/** One player and queue survive Activity recreation, foreground/background changes and media controls. */
public class PlaybackService extends Service {
    public static final String ACTION_PLAY="com.mygo.music.PLAY",ACTION_QUEUE="com.mygo.music.QUEUE",ACTION_PAUSE="com.mygo.music.PAUSE",ACTION_RESUME="com.mygo.music.RESUME",ACTION_STOP="com.mygo.music.STOP",ACTION_NEXT="com.mygo.music.NEXT",ACTION_PREVIOUS="com.mygo.music.PREVIOUS";
    interface Listener {void changed(Snapshot snapshot);}
    static final class Snapshot {
        MediaPlayer player;boolean ready,loading,playing,remote,shuffle,repeat;String uri="",title="",error="",source="",stream="";long errorId,generation;int position,duration,volume,index;HashMap<String,String> headers=new HashMap<>();JSONObject track;
    }
    public class Binder extends android.os.Binder {PlaybackService getService(){return PlaybackService.this;}}
    private final IBinder binder=new Binder();private final Handler main=new Handler(Looper.getMainLooper());private final ArrayList<WeakReference<Listener>> listeners=new ArrayList<>();
    private final Random random=new Random();private ArrayList<JSONObject> queue=new ArrayList<>();private int index=-1,percent=80,initialPosition;private long generation=System.nanoTime(),errorId=System.nanoTime();
    private boolean ready,loading,wanted,shuffle,repeat,foreground,resumeAfterFocus,ducked,closed,trackReported,currentCached;private String error="",quality="high",stream="",streamKind="";
    private final java.util.concurrent.ExecutorService mediaWorkers=java.util.concurrent.Executors.newFixedThreadPool(2);
    private String radioSource="",radioId="",radioFailure="";private long radioRevision;private boolean radioFetching,radioWaiting;
    private MediaPlayer player;private HashMap<String,String> headers=new HashMap<>();private PluginManager plugins;private PluginRemote remote;private AudioCache cache;private SharedPreferences prefs;private AudioManager audio;private MediaSession session;private long sessionId;private int notificationId=7;private AudioFocusRequest focusRequest;private VolumeProvider remoteVolume;
    private final AudioManager.OnAudioFocusChangeListener focusListener=focus->{if(closed||remote.active())return;if(focus==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK){ducked=true;applyVolume();return;}if(focus==AudioManager.AUDIOFOCUS_GAIN){ducked=false;applyVolume();if(resumeAfterFocus){resumeAfterFocus=false;resume();}return;}if(focus<0){boolean resume=wanted;pauseInternal(false);resumeAfterFocus=focus==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT&&resume;}};
    private final BroadcastReceiver noisy=new BroadcastReceiver(){@Override public void onReceive(Context context,Intent intent){if(AudioManager.ACTION_AUDIO_BECOMING_NOISY.equals(intent.getAction()))pause();}};
    @Override public IBinder onBind(Intent intent){return binder;}
    @Override public void onCreate(){super.onCreate();prefs=getSharedPreferences("library",0);audio=(AudioManager)getSystemService(AUDIO_SERVICE);plugins=new PluginManager(getApplicationContext());cache=AudioCache.shared(this);shuffle=prefs.getBoolean("shuffle",false);repeat=prefs.getBoolean("repeat",false);remote=new PluginRemote(plugins,new PluginRemote.Listener(){public void state(JSONObject value){if(closed)return;String track=value.optString("trackId");for(int i=0;i<queue.size();i++){Uri uri=Uri.parse(queue.get(i).optString("uri"));if(remote.source().equals(uri.getAuthority())&&track.equals(uri.getQueryParameter("id"))){if(index!=i){index=i;generation++;trackReported=false;}break;}}ready=remote.ready();loading=false;wanted=remote.playing();percent=Math.max(0,Math.min(100,value.optInt("volume",percent)));if(remoteVolume!=null)remoteVolume.setCurrentVolume(percent);if(wanted)recordAndCache();publish();}public void error(String message){fail(message);}});
        createSession();
        if(Build.VERSION.SDK_INT>=26){NotificationChannel channel=new NotificationChannel("mygo-playback","MyGo Music 播放",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(channel);}
        IntentFilter filter=new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY);if(Build.VERSION.SDK_INT>=33)registerReceiver(noisy,filter,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(noisy,filter);
        main.postDelayed(new Runnable(){public void run(){if(closed)return;if(index>=0&&(ready||loading)){persist();updateMediaState();}main.postDelayed(this,1000);}},1000);
    }
    // A stopped session is finished. Late framework controls must retain its old identity.
    private void createSession(){
        if(session!=null)notificationId=notificationId==Integer.MAX_VALUE?7:notificationId+1;sessionId=System.nanoTime();MediaSession created=new MediaSession(this,"MyGo Music");session=created;created.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);
        created.setCallback(new MediaSession.Callback(){private boolean current(){return !closed&&session==created;}@Override public void onPlay(){if(current())resume();}@Override public void onPause(){if(current())pause();}@Override public void onStop(){if(current())stopPlayback();}@Override public void onSkipToNext(){if(current())next();}@Override public void onSkipToPrevious(){if(current())previous();}@Override public void onSeekTo(long position){if(current())seek((int)Math.min(Integer.MAX_VALUE,position));}});
        created.setPlaybackToLocal(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());
    }
    @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent==null)return START_NOT_STICKY;if(intent.hasExtra("sessionId")&&intent.getLongExtra("sessionId",0)!=sessionId)return START_NOT_STICKY;String action=intent.getAction();try{
        if(ACTION_QUEUE.equals(action)){ensureForeground();JSONArray values=new JSONArray(readQueue(intent));ArrayList<JSONObject> next=new ArrayList<>();for(int i=0;i<values.length();i++){JSONObject item=values.getJSONObject(i);String uri=item.optString("uri");if(uri.isEmpty())throw new IOException("歌曲缺少地址");next.add(item);}if(next.isEmpty())throw new IOException("播放队列为空");queue=next;selectRadio(intent.getIntExtra("index",0));shuffle=intent.getBooleanExtra("shuffle",false);repeat=intent.getBooleanExtra("repeat",false);percent=Math.max(0,Math.min(100,intent.getIntExtra("volume",80)));quality=intent.getStringExtra("quality");if(quality==null)quality="high";prefs.edit().putString("play_quality",quality).apply();resolve(intent.getIntExtra("index",0),intent.getIntExtra("position",0),true);
        }else if(ACTION_PLAY.equals(action)){ensureForeground();clearRadio();queue=new ArrayList<>();queue.add(new JSONObject().put("uri",intent.getStringExtra("uri")).put("title",intent.getStringExtra("title")));resolve(0,intent.getIntExtra("position",0),true);
        }else if(ACTION_PAUSE.equals(action))pause();else if(ACTION_RESUME.equals(action))resume();else if(ACTION_NEXT.equals(action))next();else if(ACTION_PREVIOUS.equals(action))previous();else if(ACTION_STOP.equals(action)||"STOP".equals(action))stopPlayback();
    }catch(Exception exception){fail(exception.getMessage()==null?"播放启动失败":exception.getMessage());}return START_NOT_STICKY;}
    private String readQueue(Intent intent)throws Exception{String file=intent.getStringExtra("queueFile");if(file==null)return intent.getStringExtra("queue");if(!file.matches("mygo-queue-[A-Za-z0-9-]+\\.json"))throw new IOException("无效的播放队列文件");File path=new File(getCacheDir(),file);try{if(path.length()>8*1024*1024)throw new IOException("播放队列超过大小限制");return PluginIdentity.read(path);}finally{path.delete();}}
    static void startQueue(Context context,JSONArray queue,int index,int position,int volume,boolean shuffle,boolean repeat,String quality)throws IOException{
        byte[] data=queue.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);if(data.length>8*1024*1024)throw new IOException("播放队列超过 8 MB");Intent intent=new Intent(context,PlaybackService.class).setAction(ACTION_QUEUE).putExtra("index",index).putExtra("position",position).putExtra("volume",volume).putExtra("shuffle",shuffle).putExtra("repeat",repeat).putExtra("quality",quality);File file=null;
        try{if(data.length>200000){file=File.createTempFile("mygo-queue-",".json",context.getCacheDir());try(FileOutputStream output=new FileOutputStream(file)){output.write(data);}intent.putExtra("queueFile",file.getName());}else intent.putExtra("queue",new String(data,java.nio.charset.StandardCharsets.UTF_8));if(Build.VERSION.SDK_INT>=26)context.startForegroundService(intent);else context.startService(intent);}catch(Exception error){if(file!=null)file.delete();if(error instanceof IOException)throw (IOException)error;throw new IOException(error);}
    }

    void addListener(Listener listener){for(WeakReference<Listener> reference:listeners)if(reference.get()==listener)return;listeners.add(new WeakReference<>(listener));listener.changed(snapshot());}
    void removeListener(Listener listener){listeners.removeIf(reference->reference.get()==null||reference.get()==listener);}
    MediaSession.Token token(){return session.getSessionToken();}
    Snapshot snapshot(){Snapshot value=new Snapshot();value.player=player;value.ready=ready;value.loading=loading;value.remote=remote.active();value.playing=remote.active()?remote.playing():ready&&player!=null&&safePlaying();value.position=position();value.duration=duration();value.index=index;value.volume=percent;value.shuffle=shuffle;value.repeat=repeat;value.error=error;value.errorId=errorId;value.generation=generation;value.stream=stream;value.headers=new HashMap<>(headers);if(index>=0&&index<queue.size()){value.uri=queue.get(index).optString("uri");value.title=queue.get(index).optString("title","歌曲");value.track=queue.get(index).optJSONObject("track");Uri uri=Uri.parse(value.uri);if("plugin".equals(uri.getScheme()))value.source=uri.getAuthority();}return value;}
    private boolean safePlaying(){try{return player.isPlaying();}catch(Exception ignored){return false;}}
    private int position(){try{return remote.active()?remote.position():ready&&player!=null?player.getCurrentPosition():Math.max(0,initialPosition);}catch(Exception ignored){return 0;}}
    private int duration(){try{return remote.active()?remote.duration():ready&&player!=null?player.getDuration():0;}catch(Exception ignored){return 0;}}
    private void resolve(int target,int position,boolean play){if(closed||target<0||target>=queue.size())return;long request=++generation;quality=prefs.getString("play_quality",quality);remote.clear(true);releasePlayer();index=target;initialPosition=Math.max(0,position);wanted=play;loading=true;ready=false;trackReported=false;currentCached=false;error="";resumeAfterFocus=false;stream="";streamKind="";headers.clear();session.setActive(true);session.setPlaybackToLocal(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());ensureForeground();publish();JSONObject item=queue.get(index);String original=item.optString("uri");Uri uri=Uri.parse(original);String name=item.optString("title","歌曲");File saved=cache.find(original,quality);if(saved!=null){prepare(request,Uri.fromFile(saved),new HashMap<>(),true);return;}
        if(!"plugin".equals(uri.getScheme())){prepare(request,uri,new HashMap<>(),false);return;}
        PluginManager.PluginInfo selected=null;for(PluginManager.PluginInfo info:plugins.list())if(info.enabled&&info.id.equals(uri.getAuthority())){selected=info;break;}if(selected==null){fail("插件未启用，且歌曲尚未完整缓存");return;}final PluginManager.PluginInfo source=selected;
        if("remote".equals(source.playback)){abandonFocus();JSONArray ids=new JSONArray();int start=0;for(int i=0;i<queue.size();i++){Uri song=Uri.parse(queue.get(i).optString("uri"));if("plugin".equals(song.getScheme())&&source.id.equals(song.getAuthority())){if(i==index)start=ids.length();ids.put(song.getQueryParameter("id"));}}remoteVolume=new VolumeProvider(VolumeProvider.VOLUME_CONTROL_ABSOLUTE,100,percent){@Override public void onSetVolumeTo(int value){setVolume(value);}@Override public void onAdjustVolume(int direction){setVolume(percent+direction*5);}};session.setPlaybackToRemote(remoteVolume);remote.play(source.id,ids,start,initialPosition,(ok,raw)->{if(closed||request!=generation)return;if(!ok){fail(raw);return;}loading=false;ready=true;if(!wanted)remote.pause();publish();});return;}
        try{plugins.export(source.id,"stream",new JSONObject().put("id",uri.getQueryParameter("id")).put("quality",quality),(ok,raw)->{if(closed||request!=generation)return;if(!ok){fail(raw);return;}try{JSONObject result=new JSONObject(raw);streamKind=result.optString("type");String address=result.optString("url");if(!address.startsWith("https://")&&!address.startsWith("http://"))throw new IOException("插件未返回音频地址");HashMap<String,String> values=plugins.mediaHeaders(source.id,address,"audio",result.optJSONObject("headers"));
            // Resolve redirects without forwarding session headers to another origin.
            mediaWorkers.execute(()->{try(PluginMedia.Connection connection=PluginMedia.open(address,values,true)){String finalAddress=connection.http.getURL().toString();HashMap<String,String> finalHeaders=new HashMap<>(connection.headers);main.post(()->{if(request==generation&&!closed)prepare(request,Uri.parse(finalAddress),finalHeaders,false);});}catch(Exception error){main.post(()->{if(request==generation&&!closed)fail(error.getMessage());});}});}catch(Exception exception){fail(exception.getMessage());}});}catch(Exception exception){fail(exception.getMessage());}
    }
    private void prepare(long request,Uri address,HashMap<String,String> values,boolean cached){try{if(request!=generation||closed)return;stream=address.toString();currentCached=cached;headers=new HashMap<>(values);if(!PluginMedia.contains(headers,"User-Agent"))headers.put("User-Agent","MyGoMusic/5.11");cache.pin(cached?new File(address.getPath()):null);MediaPlayer created=new MediaPlayer();player=created;created.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());created.setWakeMode(getApplicationContext(),PowerManager.PARTIAL_WAKE_LOCK);if("http".equals(address.getScheme())||"https".equals(address.getScheme())){HashMap<String,String> playerHeaders=new HashMap<>(headers);playerHeaders.put("android-allow-cross-domain-redirect","0");created.setDataSource(this,address,playerHeaders);}else created.setDataSource(this,address);
        created.setOnPreparedListener(mp->{if(closed||request!=generation||player!=mp)return;ready=true;loading=false;applyVolume();if(initialPosition>0)mp.seekTo(Math.min(initialPosition,Math.max(0,mp.getDuration()-1)));if(wanted&&requestFocus())mp.start();else wanted=false;if(safePlaying())recordAndCache();publish();});
        created.setOnCompletionListener(mp->{if(request!=generation||closed)return;if(repeat)resolve(index,0,true);else next();});created.setOnErrorListener((mp,what,extra)->{if(request!=generation||closed)return true;if(cached&&index>=0&&index<queue.size())cache.remove(queue.get(index).optString("uri"),quality);fail(cached?"缓存音频无法播放，已清理，请重新播放":"音频播放失败："+what+" / "+extra);return true;});created.prepareAsync();publish();
    }catch(Exception exception){fail(exception.getMessage()==null?"音频无法准备":exception.getMessage());}}
    private void recordAndCache(){refillRadio();if(trackReported||index<0||index>=queue.size())return;trackReported=true;String original=queue.get(index).optString("uri"),title=queue.get(index).optString("title","歌曲");ArrayList<String> recent=new ArrayList<>();String old=prefs.getString("recent","");if(!old.isEmpty())recent.addAll(Arrays.asList(old.split("\n")));recent.remove(original);recent.add(0,original);while(recent.size()>30)recent.remove(recent.size()-1);prefs.edit().putString("recent",String.join("\n",recent)).apply();Uri uri=Uri.parse(original);if(currentCached||!"plugin".equals(uri.getScheme()))return;try{plugins.export(uri.getAuthority(),"played",new JSONObject().put("id",uri.getQueryParameter("id")),(ok,raw)->{});}catch(Exception ignored){}if(!streamKind.equals("hls")&&prefs.getBoolean("auto_cache",true)&&(stream.startsWith("https://")||stream.startsWith("http://")))cache.store(original,title,quality,stream,headers,(ok,message)->prefs.edit().putString("cache_status",message).apply());}
    private void clearRadio(){radioRevision++;radioSource="";radioId="";radioFailure="";radioFetching=false;radioWaiting=false;}
    private void selectRadio(int start){clearRadio();if(start<0||start>=queue.size())return;JSONObject item=queue.get(start);String station=item.optString("stationId");Uri uri=Uri.parse(item.optString("uri"));if(!station.isEmpty()&&"plugin".equals(uri.getScheme())){radioId=station;radioSource=uri.getAuthority();}}
    private void refillRadio(){
        if(closed||radioId.isEmpty()||radioFetching||!radioFailure.isEmpty()||!radioWaiting&&queue.size()-index>3)return;
        radioFetching=true;long ticket=radioRevision;String source=radioSource,station=radioId;
        plugins.export(source,"stationNext",SourceBrowser.arg("id",station),(ok,raw)->{
            if(closed||ticket!=radioRevision)return;radioFetching=false;
            try{if(!ok)throw new IOException(raw);JSONArray tracks=new JSONArray(raw);HashSet<String> seen=new HashSet<>();for(int i=Math.max(0,queue.size()-50);i<queue.size();i++)seen.add(queue.get(i).optString("uri"));int added=0;
                for(int i=0;i<tracks.length()&&added<100;i++){JSONObject track=tracks.optJSONObject(i);if(track==null||track.optString("id").isEmpty()||track.optBoolean("unavailable"))continue;String uri=new Uri.Builder().scheme("plugin").authority(source).appendQueryParameter("id",track.getString("id")).build().toString();if(!seen.add(uri))continue;track.put("_stationId",station);queue.add(new JSONObject().put("uri",uri).put("title",SourceBrowser.trackName(track)).put("track",track).put("stationId",station));added++;}
                if(added==0)throw new IOException("电台没有返回新歌曲，请稍后重试");while(queue.size()>500&&index>50){queue.remove(0);index--;}
                if(radioWaiting){radioWaiting=false;resolve(index+1,0,wanted);}else publish();
            }catch(Exception error){radioFailure=error.getMessage()==null?"电台加载失败":error.getMessage();if(radioWaiting){String failure=radioFailure;radioFailure="";fail(failure);}}
        });
    }
    void enqueue(JSONObject value,boolean next)throws Exception{
        if(queue.size()>=500)throw new IOException("播放队列已达到 500 首，请先移除部分歌曲");String uri=value.optString("uri");if(uri.isEmpty())throw new IOException("歌曲缺少地址");clearRadio();JSONObject item=new JSONObject(value.toString());if(queue.isEmpty()){queue.add(item);index=0;initialPosition=0;}else queue.add(next?Math.max(0,index+1):queue.size(),item);publish();
    }
    void moveQueue(int from,int to){if(from<0||to<0||from>=queue.size()||to>=queue.size()||from==to)return;clearRadio();JSONObject current=index>=0?queue.get(index):null;JSONObject moving=queue.remove(from);queue.add(to,moving);index=queue.indexOf(current);if(remote.active())resolve(index,position(),wanted);else publish();}
    void removeQueue(int at){if(at<0||at>=queue.size())return;clearRadio();boolean selected=at==index;queue.remove(at);if(queue.isEmpty()){stopPlayback();index=-1;publish();return;}if(at<index)index--;if(selected)resolve(Math.min(at,queue.size()-1),0,wanted);else if(remote.active())resolve(index,position(),wanted);else publish();}
    void clearQueue(){stopPlayback();queue.clear();index=-1;publish();}
    void pause(){pauseInternal(true);}
    private void pauseInternal(boolean clearResume){if(closed)return;if(clearResume)resumeAfterFocus=false;wanted=false;if(remote.active())remote.pause();else if(ready&&player!=null)try{player.pause();}catch(Exception ignored){}if(clearResume&&!remote.active())abandonFocus();publish();}
    void resume(){if(closed)return;if(radioWaiting){radioFailure="";wanted=true;refillRadio();return;}resumeAfterFocus=false;if(index<0||queue.isEmpty())return;wanted=true;ensureForeground();session.setActive(true);if(remote.active()){remote.resume();publish();}else if(ready&&player!=null){if(requestFocus()){player.start();recordAndCache();publish();}else{wanted=false;publish();}}else if(!loading)resolve(index,initialPosition,true);else publish();}
    void seek(int position){if(closed)return;initialPosition=Math.max(0,position);if(remote.active())remote.seek(initialPosition);else if(ready&&player!=null)player.seekTo(Math.min(initialPosition,Math.max(0,player.getDuration()-1)));publish();}
    void setVolume(int value){percent=Math.max(0,Math.min(100,value));if(remote.active())remote.volume(percent);else applyVolume();publish();}
    void setModes(boolean shuffled,boolean repeated){shuffle=shuffled;repeat=repeated;prefs.edit().putBoolean("shuffle",shuffle).putBoolean("repeat",repeat).apply();publish();}
    void toggle(){if(loading){if(wanted)pause();else resume();}else if(snapshot().playing)pause();else resume();}
    JSONArray queueSnapshot(){JSONArray copy=new JSONArray();for(JSONObject item:queue)try{copy.put(new JSONObject(item.toString()));}catch(JSONException ignored){}return copy;}
    void playQueueIndex(int target){if(!closed&&target>=0&&target<queue.size())resolve(target,0,true);}
    void next(){if(closed)return;if(queue.isEmpty())return;if(!radioId.isEmpty()&&index+1>=queue.size()){radioWaiting=true;loading=true;wanted=true;publish();if(!radioFailure.isEmpty()){String failure=radioFailure;radioFailure="";fail(failure);}else refillRadio();return;}resolve(shuffle?random.nextInt(queue.size()):(index+1)%queue.size(),0,true);}
    void previous(){if(closed)return;if(queue.isEmpty())return;resolve(index<=0?queue.size()-1:index-1,0,true);}
    void stopPlayback(){if(closed)return;clearRadio();initialPosition=position();persist();++generation;wanted=false;loading=false;resumeAfterFocus=false;remote.clear(true);releasePlayer();cache.pin(null);abandonFocus();session.setActive(false);foreground=false;stopForeground(true);publish();session.release();createSession();stopSelf();}
    private boolean requestFocus(){if(Build.VERSION.SDK_INT>=26){if(focusRequest==null)focusRequest=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setOnAudioFocusChangeListener(focusListener,main).build();return audio.requestAudioFocus(focusRequest)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED;}return audio.requestAudioFocus(focusListener,AudioManager.STREAM_MUSIC,AudioManager.AUDIOFOCUS_GAIN)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED;}
    private void abandonFocus(){if(Build.VERSION.SDK_INT>=26&&focusRequest!=null)audio.abandonAudioFocusRequest(focusRequest);else audio.abandonAudioFocus(focusListener);}
    private void applyVolume(){if(ready&&player!=null)player.setVolume(percent/100f*(ducked?0.2f:1f),percent/100f*(ducked?0.2f:1f));}
    private void releasePlayer(){ready=false;if(player!=null){player.setOnPreparedListener(null);player.setOnCompletionListener(null);player.setOnErrorListener(null);player.release();player=null;}}
    private void fail(String message){if(closed)return;error=message==null||message.isEmpty()?"播放失败":message;errorId++;wanted=false;loading=false;resumeAfterFocus=false;remote.clear(true);releasePlayer();cache.pin(null);abandonFocus();publish();}
    private void persist(){Snapshot value=snapshot();if(!value.uri.isEmpty())prefs.edit().putString("last_uri",value.uri).putInt("last_pos",value.position).apply();}
    private void publish(){if(closed)return;Snapshot value=snapshot();persist();updateMediaState();if(foreground)getSystemService(NotificationManager.class).notify(notificationId,notification());for(Iterator<WeakReference<Listener>> iterator=listeners.iterator();iterator.hasNext();){Listener listener=iterator.next().get();if(listener==null)iterator.remove();else listener.changed(value);}}
    private void updateMediaState(){Snapshot value=snapshot();int state=!error.isEmpty()?PlaybackState.STATE_ERROR:loading?PlaybackState.STATE_BUFFERING:value.playing?PlaybackState.STATE_PLAYING:ready?PlaybackState.STATE_PAUSED:PlaybackState.STATE_STOPPED;PlaybackState.Builder playback=new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS|PlaybackState.ACTION_SEEK_TO|PlaybackState.ACTION_STOP).setState(state,value.position,value.playing?1f:0f,SystemClock.elapsedRealtime());if(!error.isEmpty())playback.setErrorMessage(error);session.setPlaybackState(playback.build());session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,value.title.isEmpty()?"MyGo Music":value.title).putString(MediaMetadata.METADATA_KEY_MEDIA_ID,value.uri).putLong(MediaMetadata.METADATA_KEY_DURATION,value.duration).build());}
    private PendingIntent action(String action,int request){return PendingIntent.getService(this,request,new Intent(this,PlaybackService.class).setAction(action).setData(Uri.parse("mygo-playback://controls/"+sessionId+"/"+action)).putExtra("sessionId",sessionId),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);}
    private Notification notification(){Snapshot value=snapshot();PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder builder=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"mygo-playback"):new Notification.Builder(this);builder.setContentTitle(value.title.isEmpty()?"MyGo Music":value.title).setContentText(!error.isEmpty()?error:loading?"正在准备音频":value.playing?"正在播放":"已暂停").setSmallIcon(R.drawable.ic_launcher).setContentIntent(open).setColor(Color.rgb(147,88,190)).setVisibility(Notification.VISIBILITY_PUBLIC).setOngoing(value.playing||loading).setOnlyAlertOnce(true).setDeleteIntent(action(ACTION_STOP,14));builder.addAction(new Notification.Action.Builder(0,"上一首",action(ACTION_PREVIOUS,10)).build());builder.addAction(new Notification.Action.Builder(0,value.playing?"暂停":"继续",action(value.playing?ACTION_PAUSE:ACTION_RESUME,11)).build());builder.addAction(new Notification.Action.Builder(0,"下一首",action(ACTION_NEXT,12)).build());builder.addAction(new Notification.Action.Builder(0,"停止",action(ACTION_STOP,13)).build());builder.setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1,2));return builder.build();}
    private void ensureForeground(){if(!foreground){foreground=true;session.setActive(true);startForeground(notificationId,notification());}}
    @Override public void onDestroy(){closed=true;clearRadio();main.removeCallbacksAndMessages(null);try{unregisterReceiver(noisy);}catch(Exception ignored){}remote.close();releasePlayer();cache.pin(null);abandonFocus();plugins.close();mediaWorkers.shutdownNow();session.release();listeners.clear();super.onDestroy();}
}
